comment Jensen's device. A parameter called by name is evaluated again
  every time it is used, in the environment of the call, so a procedure
  can be handed an expression together with the variable it depends on.
  The device is J. Jensen's, of Regnecentralen, Copenhagen;
begin
  integer i, j;
  real array a[1:3], b[1:3];
  real array m[1:3, 1:3];

  real procedure Sum(k, lo, hi, term);
    value lo, hi;
    integer k, lo, hi;
    real term;
  begin
    real s;
    s := 0;
    for k := lo step 1 until hi do
      s := s + term;
    Sum := s
  end;


  comment The harmonic number H(100);
  outstring(1, "H(100) = "); outreal(1, Sum(i, 1, 100, 1/i)); outstring(1, "\n");

  comment An inner product: the term names the subscript;
  for i := 1 step 1 until 3 do begin a[i] := i; b[i] := 10 × i end;
  outstring(1, "a.b = "); outreal(1, Sum(i, 1, 3, a[i] × b[i])); outstring(1, "\n");

  comment A double sum: Sum inside the term of Sum;
  for i := 1 step 1 until 3 do
    for j := 1 step 1 until 3 do m[i, j] := i × j;
  outstring(1, "sum of m = ");
  outreal(1, Sum(i, 1, 3, Sum(j, 1, 3, m[i, j]))); outstring(1, "\n");

  comment The trace, with the same procedure;
  outstring(1, "trace of m = "); outreal(1, Sum(i, 1, 3, m[i, i])); outstring(1, "\n");

  comment Sum of squares of the odd numbers below 20;
  outstring(1, "odd squares = ");
  outreal(1, Sum(i, 1, 10, (2 × i - 1) ↑ 2)); outstring(1, "\n");

  comment After the call, the controlled variable has been left by the
    for statement inside Sum. The Report says its value is then undefined
    (4.6.5), and here it is the value that failed the test;
  outstring(1, "i after the last call = "); outinteger(1, i); outstring(1, "\n")
end

comment Knuth's test as printed in Algol Bulletin 17, page 7 (July 1964),
  from the scan in sources/knuth-man-or-boy-1964. Two changes: the
  printed outreal has one parameter, and here it is given the channel
  number the Modified Report's outreal takes, and the underlined word
  delimiters are written as reserved words. Knuth asked "What should the
  answer be?" and conjectured, by hand, 73 - 119 - 177 + 102 = -121;
begin real procedure A(k, x1, x2, x3, x4, x5);
           value k; integer k;
           begin real procedure B;
                    begin k := k - 1;
                          B := A := A(k, B, x1, x2, x3, x4)
                    end;
                 if k ≤ 0 then A := x4 + x5 else B
           end;
      outreal(1, A(10, 1, -1, -1, 1, 0))
end;

comment How many times the Report evaluates each part of a for statement.
  The step-until element is defined by its expansion (4.6.4.2):
      V := A,
  L1: if (V - C) × sign(B) > 0 then go to element exhausted,
      S,
      V := V + B,
      go to L1
  (with semicolons, which cannot be written in a comment), so the limit C is evaluated once for every test, and the step B twice
  for every time round, once in the test and once in the increment.
  With ten times round there are eleven tests and ten increments;
begin
  integer na, nb, nc, nv, i, count;

  integer procedure A; begin na := na + 1; A := 1 end;
  integer procedure B; begin nb := nb + 1; B := 1 end;
  integer procedure C; begin nc := nc + 1; C := 10 end;

  count := 0;
  for i := A step B until C do count := count + 1;
  outstring(1, "body ran "); outinteger(1, count); outstring(1, "\n");
  outstring(1, "A evaluated "); outinteger(1, na); outstring(1, "\n");
  outstring(1, "B evaluated "); outinteger(1, nb); outstring(1, "\n");
  outstring(1, "C evaluated "); outinteger(1, nc); outstring(1, "\n");

  comment A limit that changes inside the loop is seen at once;
  begin
    integer n;
    n := 3; count := 0;
    for i := 1 step 1 until n do begin count := count + 1; if i = 2 then n := 5 end;
    outstring(1, "with the limit raised from 3 to 5, the body ran "); outinteger(1, count); outstring(1, "\n")
  end;

  comment A while element evaluates its expression before each test;
  count := 0;
  for i := 1, i + i while i < 100 do count := count + 1;
  outstring(1, "1, i + i while i < 100: "); outinteger(1, count);
  outstring(1, " times, i = "); outinteger(1, i); outstring(1, "\n");

  comment The parameter called by name is evaluated at each use;
  begin
    integer procedure twice(x); integer x; twice := x + x;
    integer procedure next; begin nv := nv + 1; next := nv end;
    nv := 0;
    outstring(1, "twice(next) = "); outinteger(1, twice(next));
    outstring(1, " (next was called "); outinteger(1, nv); outstring(1, "times)\n")
  end
end

comment 4.2.3: in an assignment the subscript expressions of the left
  part are evaluated first, from left to right, then the expression, and
  then its value is assigned to all the left part variables;
begin
  integer i;
  integer array a[1:3];

  i := 1;
  a[i] := i := 2;
  outstring(1, "a[i] := i := 2 with i = 1 gives a[1] = "); outinteger(1, a[1]);
  outstring(1, "and i = "); outinteger(1, i); outstring(1, "\n");

  begin
    integer procedure bump; begin i := i + 1; bump := 10 × i end;
    i := 1;
    a[i] := bump;
    outstring(1, "a[i] := bump, where bump sets i to 2 and has the value 20: a[1] = ");
    outinteger(1, a[1]); outstring(1, "a[2] = "); outinteger(1, a[2]); outstring(1, "\n")
  end;

  comment A real assigned to an integer is rounded: entier(E + 0.5) (4.2.4);
  i := 2.5; outinteger(1, i);
  i := -2.5; outinteger(1, i);
  i := 2.49; outinteger(1, i);
  outstring(1, "\n")
end

comment Each line of output tells the Revised Report from the Electrologica
  X1 system of 1962, where the two differ, as far as the documents say.
  The numbers are those of the "special properties" in the X1 user manual
  (Kruseman Aretz 2003, section 1.3). Run it with and without --x1.
  The declarations are in the order the X1 requires (property 15), and
  every formal parameter is specified (property 19), so both accept it;
begin
  integer i, seen, calls, abcdefghiX, n;
  real x;

  integer procedure stride;
  begin if calls = 0 then seen := i; calls := calls + 1; stride := 1 end;

  integer procedure note(k); value k; integer k;
  begin outinteger(1, k); note := k end;

  procedure order(a, b); value a, b; integer b; integer a; ;

  integer procedure half(y); value y; real y; half := y / 2;

  comment Property 11: the X1 evaluates the step before it assigns the
    initial value, so the first call of stride sees the old value of i;
  i := 7; calls := 0;
  for i := 1 step stride until 1 do ;
  outstring(1, "11. the step first saw i = "); outinteger(1, seen); outstring(1, "\n");

  comment Property 22: values are assigned in the order of specification;
  outstring(1, "22. value parameters evaluated in the order: ");
  order(note(1), note(2)); outstring(1, "\n");

  comment Property 18: the value of a function is not converted to the
    type it is declared with. half(3) is 1.5, rounded to 2 by the Report;
  outstring(1, "18. the integer procedure half(3) = "); outreal(1, half(3)); outstring(1, "\n");

  comment Property 3: only the first nine symbols of an identifier count,
    so abcdefghiY inside the block is the same identifier as abcdefghiX
    and hides it;
  abcdefghiX := 0;
  begin integer abcdefghiY; abcdefghiX := 1 end;
  outstring(1, "3. the outer abcdefghiX = "); outinteger(1, abcdefghiX); outstring(1, "\n");

  comment A real variable of the X1 keeps a mantissa of 40 bits, but
    1/3 is computed with 52 (X1-X8 comparison, section 3.2);
  x := 1 / 3;
  outstring(1, "3.2 x := 1/3, x - 1/3 = "); outreal(1, x - 1 / 3); outstring(1, "\n");

  comment And a sum accumulated in a variable loses the difference;
  x := 0;
  for n := 1 step 1 until 1000 do x := x + 1 / n;
  outstring(1, "3.2 the sum of 1/n to 1000 = "); outreal(1, x); outstring(1, "\n")
end

