comment Reads numbers until a negative one, and prints their mean;
begin
  real x, sum;
  integer n;
  sum := 0; n := 0;
next:
  inreal(0, x);
  if x ≥ 0 then begin sum := sum + x; n := n + 1; go to next end;
  outinteger(1, n); outstring(1, "numbers, mean "); outreal(1, sum / n); outstring(1, "\n")
end

comment Labels passed as parameters, and go to statements that leave
  procedures. A label belongs to one activation of its block, so a jump to
  the label m passed down by the activation with n = 1 resumes that
  activation, abandoning those inside it;
begin
  procedure p(n, l);
    value n; integer n; label l;
  begin
    outstring(1, "enter "); outinteger(1, n); outstring(1, "\n");
    if n = 0 then go to l;
    p(n - 1, m);
    outstring(1, "returned to "); outinteger(1, n); outstring(1, "\n");
    go to out;
  m: outstring(1, "jumped to m of "); outinteger(1, n); outstring(1, "\n");
  out:
  end;

  comment Leaving a deep recursion at once, from a function designator in
    the middle of an expression;
  integer procedure search(k);
    value k; integer k;
  begin
    if k = 37 then go to found;
    search := search(k + 1)
  end;

  p(3, done);
done: outstring(1, "done\n");
  outinteger(1, 1 + search(1));
  outstring(1, "not printed\n");
found: outstring(1, "found 37\n")
end

comment The towers of Hanoi. Every move for three discs, then the number
  of moves for ten;
begin
  integer moves;
  procedure hanoi(n, from, to, via, show);
    value n, from, to, via; integer n, from, to, via; Boolean show;
  begin
    if n > 0 then
    begin
      hanoi(n - 1, from, via, to, show);
      moves := moves + 1;
      if show then
      begin
        outstring(1, "disc "); outinteger(1, n); outstring(1, "from ");
        outinteger(1, from); outstring(1, "to "); outinteger(1, to); outstring(1, "\n")
      end;
      hanoi(n - 1, via, to, from, show)
    end
  end;
  moves := 0;
  hanoi(3, 1, 3, 2, true);
  moves := 0;
  hanoi(10, 1, 3, 2, false);
  outinteger(1, moves); outstring(1, "moves for ten discs\n")
end

comment Labels, switches and go to statements (3.5, 4.3).
  A label may be an unsigned integer, as in the Revised Report.
  A go to statement whose switch designator is undefined, because the
  subscript is out of range, is a dummy statement (4.3.5).
  A go to statement may enter a compound or conditional statement, but
  not a block or a for statement;
begin
  integer i, n;
  switch s := one, two, if n > 10 then big else small, 99;

  for i := 1 step 1 until 5 do
  begin
    n := i × 4;
    go to s[i];
  one: outstring(1, "one\n"); go to next;
  two: outstring(1, "two\n"); go to next;
  big: outstring(1, "big\n"); go to next;
  small: outstring(1, "small\n"); go to next;
  99: outstring(1, "ninety-nine\n"); go to next;
  next:
  end;

  comment s[7] is undefined, so this is a dummy statement;
  go to s[7];
  outstring(1, "go to s[7] did nothing\n");

  comment Into the middle of a conditional statement. After the jump the
    rest of the then-branch is done and the else-branch is not;
  n := 0;
  go to inside;
  if n = 1 then
  begin
    outstring(1, "not printed\n");
  inside: outstring(1, "inside the then-branch\n")
  end
  else outstring(1, "not printed either\n");
  outstring(1, "after the conditional\n")
end

comment Knuth's "man or boy" test, Algol Bulletin 17 (July 1964), page 7,
  printed for k = 0 to 12. Knuth wrote that it "may separate the
  man-compilers from the boy-compilers", that he had no man-compiler,
  and that his conjecture from hand calculation, "probably wrong", was
  -121 for k = 10. The answer compilers found is -67. The program as
  printed is in man-or-boy-1964.alg;
begin
  integer k;
  real procedure A(k, x1, x2, x3, x4, x5);
    value k; integer k; real x1, x2, x3, x4, x5;
  begin
    real procedure B;
    begin k := k - 1;
          B := A := A(k, B, x1, x2, x3, x4)
    end;
    if k <= 0 then A := x4 + x5 else B
  end;
  for k := 0 step 1 until 12 do
  begin
    outinteger(1, k); outreal(1, A(k, 1, -1, -1, 1, 0)); outstring(1, "\n")
  end
end

comment Own variables keep their values from one activation of their block
  to the next (5). Here an own counter in a procedure, and an own array.
  Variables that are not own start, in this implementation, at zero: the
  Report leaves their values undefined;
begin
  integer i;
  integer procedure counter;
  begin
    own integer n;
    n := n + 1;
    counter := n
  end;

  procedure remember(x);
    value x; integer x;
  begin
    own integer count;
    integer k;
    own integer array seen[1:5];
    count := count + 1;
    seen[count] := x;
    outstring(1, "seen:");
    for k := 1 step 1 until count do outinteger(1, seen[k]);
    outstring(1, "\n")
  end;

  for i := 1 step 1 until 3 do outinteger(1, counter);
  outstring(1, "\n");
  remember(10); remember(20); remember(30)
end

comment Exponentiation, 3.3.4.3 and 3.3.5. The operator groups from the
  left, so 2↑3↑2 is (2↑3)↑2, and a sign before an expression applies after ↑,
  so -2↑2 is -(2↑2). The type of i↑j depends on the value of j: an integer
  for j > 0, a real for j < 0;
begin
  outinteger(1, 2 ↑ 3 ↑ 2); outstring(1, "\n");
  outinteger(1, -2 ↑ 2); outstring(1, "\n");
  outinteger(1, 2 ↑ 10); outstring(1, "\n");
  outreal(1, 2 ↑ (-1)); outstring(1, "\n");
  outreal(1, 2.0 ↑ 3); outstring(1, "\n");
  outreal(1, 9 ↑ 0.5); outstring(1, "\n");
  outinteger(1, 7 ↑ 0); outstring(1, "\n");
  outreal(1, 0 ↑ 2.5); outstring(1, "\n");
  outinteger(1, 7 ÷ 2); outinteger(1, -7 ÷ 2); outinteger(1, 7 ÷ (-2)); outstring(1, "\n");
  outreal(1, 7 / 2); outstring(1, "\n");
  outinteger(1, 1 + 2 × 3 ↑ 2); outstring(1, "\n");
  outreal(1, abs(-7) / 2); outinteger(1, iabs(-7) ÷ 2); outstring(1, "\n");
  outinteger(1, entier(-2.5)); outinteger(1, sign(-0.1)); outstring(1, "\n");
  outinteger(1, 0 ↑ 0)
end

comment The eight queens, by backtracking, after Wirth's program in
  "Program development by stepwise refinement" (1971). Prints the first
  solution and the number of solutions;
begin
  integer i, count;
  integer array x[1:8];
  Boolean array a[1:8], b[2:16], c[-7:7];

  procedure try(i);
    value i; integer i;
  begin
    integer j, k;
    for j := 1 step 1 until 8 do begin
      if a[j] ∧ b[i + j] ∧ c[i - j] then
      begin
        x[i] := j;
        a[j] := b[i + j] := c[i - j] := false;
        if i < 8 then try(i + 1)
        else
        begin
          count := count + 1;
          if count = 1 then
          begin
            for k := 1 step 1 until 8 do outinteger(1, x[k]);
            outstring(1, "\n")
          end
        end;
        a[j] := b[i + j] := c[i - j] := true
      end
    end
  end;

  for i := 1 step 1 until 8 do a[i] := true;
  for i := 2 step 1 until 16 do b[i] := true;
  for i := -7 step 1 until 7 do c[i] := true;
  count := 0;
  try(1);
  outinteger(1, count); outstring(1, "solutions\n")
end

comment Hoare's quicksort (Algorithm 64, CACM 4, 1961, in spirit if not
  in letter), on an array called by name;
begin
  integer k, seed;
  integer array v[1:20];

  procedure quicksort(a, lo, hi);
    value lo, hi; integer lo, hi; integer array a;
  begin
    integer i, j, pivot, t;
    if lo < hi then
    begin
      pivot := a[(lo + hi) ÷ 2];
      i := lo; j := hi;
    scan:
      for i := i while a[i] < pivot do i := i + 1;
      for j := j while a[j] > pivot do j := j - 1;
      if i ≤ j then
      begin
        t := a[i]; a[i] := a[j]; a[j] := t;
        i := i + 1; j := j - 1
      end;
      if i ≤ j then go to scan;
      quicksort(a, lo, j);
      quicksort(a, i, hi)
    end
  end;

  seed := 7;
  for k := 1 step 1 until 20 do
  begin
    seed := (seed × 1103 + 12345) - (seed × 1103 + 12345) ÷ 1000 × 1000;
    v[k] := seed
  end;
  quicksort(v, 1, 20);
  for k := 1 step 1 until 20 do outinteger(1, v[k]);
  outstring(1, "\n")
end

comment The examples of procedure declarations in section 5.4.2 of the
  Revised Report, with a program to call them. The procedure texts are
  those of the printing in CACM 6(1), 1963, page 14, apart from the
  character set. They use the parameter delimiter
  ") letter string :(" for the comma between parameters, as in
  Spur (A) Order: (7) Result: (V);
begin
  procedure Spur(a) Order: (n) Result: (s);
    value n;
    array a; integer n; real s;
  begin integer k;
    s := 0;
    for k := 1 step 1 until n do s := s + a[k, k]
  end;

  procedure Transpose(a) Order: (n);
    value n;
    array a; integer n;
  begin real w; integer i, k;
    for i := 1 step 1 until n do
      for k := 1 + i step 1 until n do
      begin w := a[i, k];
        a[i, k] := a[k, i];
        a[k, i] := w
      end
  end Transpose;

  integer procedure Step(u); real u;
    Step := if 0 ≤ u ∧ u ≤ 1 then 1 else 0;

  procedure Absmax(a) size: (n, m) Result: (y) Subscripts: (i, k);
    comment The absolute greatest element of the matrix a, of size n by m,
      is transferred to y, and the subscripts of this element to i and k;
    array a; integer n, m, i, k; real y;
  begin integer p, q;
    y := 0;
    for p := 1 step 1 until n do
      for q := 1 step 1 until m do
        if abs(a[p, q]) > y then
        begin y := abs(a[p, q]); i := p; k := q end
  end Absmax;

  procedure Innerproduct(a, b) Order: (k, p) Result: (y);
    value k;
    integer k, p; real y, a, b;
  begin real s;
    s := 0;
    for p := 1 step 1 until k do s := s + a × b;
    y := s
  end Innerproduct;

  real array A[1:3, 1:3], B[1:3];
  integer i, j, r, c;
  real v;

  for i := 1 step 1 until 3 do
  begin
    B[i] := i;
    for j := 1 step 1 until 3 do A[i, j] := 10 × i + j
  end;
  A[2, 3] := -50;

  Spur(A) Order: (3) Result: (v);
  outstring(1, "Spur(A) = "); outreal(1, v); outstring(1, "\n");

  Absmax(A) size: (3, 3) Result: (v) Subscripts: (r, c);
  outstring(1, "Absmax: "); outreal(1, v); outstring(1, "at "); outinteger(1, r); outinteger(1, c);
  outstring(1, "\n");

  comment Jensen's device: a and b are called by name and depend on p;
  Innerproduct(A[2, j], B[j], 3, j, v);
  outstring(1, "row 2 of A times B = "); outreal(1, v); outstring(1, "\n");

  Transpose(A) Order: (3);
  outstring(1, "transposed, A[3, 2] = "); outreal(1, A[3, 2]); outstring(1, "\n");

  for i := -1, 0, 1, 2 do outinteger(1, Step(i / 2));
  outstring(1, "\n")
end

comment The primes below n, by the sieve of Eratosthenes. The bound of
  the array is read from the input, so it is fixed only when the block
  that declares the array is entered (5.2.4.2);
begin
  integer n;
  ininteger(0, n);
  begin
    integer i, j, count;
    Boolean array composite[2:n];
    count := 0;
    for i := 2 step 1 until n do
    begin
      if ¬composite[i] then
      begin
        count := count + 1;
        outinteger(1, i);
        for j := i × i step i until n do composite[j] := true
      end
    end;
    outstring(1, "\n"); outinteger(1, count); outstring(1, "primes\n")
  end
end

'COMMENT' QUOTE STROPPING, AS ON MANY MACHINES OF THE 1960S. THE WORD
  DELIMITERS ARE IN QUOTES, AND SPACES ARE IGNORED OUTSIDE STRINGS, SO
  AN IDENTIFIER MAY CONTAIN THEM, AS IN THE REFERENCE LANGUAGE;
'BEGIN'
  'INTEGER' NUMBER OF TERMS, K;
  'INTEGER' 'PROCEDURE' FACTORIAL(N); 'VALUE' N; 'INTEGER' N;
    FACTORIAL := 'IF' N 'LE' 1 'THEN' 1 'ELSE' N * FACTORIAL(N - 1);
  NUMBER OF TERMS := 10;
  'FOR' K := 1 'STEP' 1 'UNTIL' NUMBEROFTERMS 'DO'
    OUTINTEGER(1, FACTORIAL(K));
  OUTSTRING(1, "\n")
'END'

comment Why swap cannot be written with parameters called by name. With
  i = 1 and a[1] = 5, swap(i, a[i]) does t := i, then i := a[i], so i
  becomes 5, then a[i] := t, which is a[5] := 1: the subscript is
  evaluated again, after i has changed. This is the standard example of
  the trouble with call by name;
begin
  integer i;
  integer array a[1:5];

  procedure swap(x, y);
    integer x, y;
  begin
    integer t;
    t := x; x := y; y := t
  end;

  procedure show;
  begin
    integer k;
    outstring(1, "i = "); outinteger(1, i); outstring(1, " a =");
    for k := 1 step 1 until 5 do outinteger(1, a[k]);
    outstring(1, "\n")
  end;


  i := 1; a[1] := 5;
  show;
  swap(a[i], i);
  outstring(1, "after swap(a[i], i):\n"); show;

  i := 1; a[1] := 5; a[5] := 0;
  swap(i, a[i]);
  outstring(1, "after swap(i, a[i]):\n"); show
end

comment An array called by value is copied at the call, so the procedure
  can change its copy without changing the actual array. Called by name,
  the array is shared;
begin
  integer array x[1:3];
  procedure byvalue(a); value a; integer array a;
  begin a[1] := 99; outstring(1, "inside, by value: "); outinteger(1, a[1]); outstring(1, "\n") end;
  procedure byname(a); integer array a;
  begin a[1] := 99; outstring(1, "inside, by name: "); outinteger(1, a[1]); outstring(1, "\n") end;

  x[1] := 1;
  byvalue(x); outstring(1, "after: "); outinteger(1, x[1]); outstring(1, "\n");
  byname(x); outstring(1, "after: "); outinteger(1, x[1]); outstring(1, "\n")
end
